  "statement": "INSERT INTO workspace.mlpabdb7840.churntraining9b67c4 WITH labels AS (SELECT account_id, CAST(label_time AS BIGINT) AS label_time, CAST(churned AS BIGINT) AS churned FROM read_files('/Volumes/workspace/mlpabdb7840/raw/labels.csv', format => 'csv', header => true)), tx AS (SELECT account_id, CAST(event_time AS BIGINT) AS event_time, CAST(amount AS DOUBLE) AS amount, CAST(balance AS DOUBLE) AS balance FROM read_files('/Volumes/workspace/mlpabdb7840/raw/transactions.csv', '/Volumes/workspace/mlpabdb7840/raw/transactions_late.csv', format => 'csv', header => true)), pr AS (SELECT account_id, CAST(event_time AS BIGINT) AS event_time, CAST(credit_score AS BIGINT) AS credit_score, CAST(tier AS STRING) AS tier FROM read_files('/Volumes/workspace/mlpabdb7840/raw/profiles.csv', format => 'csv', header => true)), ac AS (SELECT account_id, CAST(event_time AS BIGINT) AS event_time, CAST(sessions_7d AS BIGINT) AS sessions_7d FROM read_files('/Volumes/workspace/mlpabdb7840/raw/activity.csv', format => 'csv', header => true)), hl AS (SELECT account_id, CAST(event_time AS BIGINT) AS event_time, CAST(health_score AS DOUBLE) AS health_score FROM read_files('/Volumes/workspace/mlpabdb7840/raw/account_health.csv', format => 'csv', header => true)), tx_pit AS (SELECT * FROM (SELECT l.account_id, l.label_time, t.amount, t.balance, ROW_NUMBER() OVER (PARTITION BY l.account_id, l.label_time ORDER BY t.event_time DESC) AS rn FROM labels l LEFT JOIN tx t ON t.account_id = l.account_id AND t.event_time <= l.label_time) WHERE rn = 1), pr_pit AS (SELECT * FROM (SELECT l.account_id, l.label_time, p.credit_score, p.tier, ROW_NUMBER() OVER (PARTITION BY l.account_id, l.label_time ORDER BY p.event_time DESC) AS rn FROM labels l LEFT JOIN pr p ON p.account_id = l.account_id AND p.event_time <= l.label_time) WHERE rn = 1), ac_pit AS (SELECT * FROM (SELECT l.account_id, l.label_time, a.sessions_7d, ROW_NUMBER() OVER (PARTITION BY l.account_id, l.label_time ORDER BY a.event_time DESC) AS rn FROM labels l LEFT JOIN ac a ON a.account_id = l.account_id AND a.event_time <= l.label_time) WHERE rn = 1), hl_pit AS (SELECT * FROM (SELECT l.account_id, l.label_time, h.health_score, ROW_NUMBER() OVER (PARTITION BY l.account_id, l.label_time ORDER BY h.event_time DESC) AS rn FROM labels l LEFT JOIN hl h ON h.account_id = l.account_id AND h.event_time <= l.label_time) WHERE rn = 1) SELECT l.account_id, l.label_time, t.amount, t.balance, p.credit_score, p.tier, a.sessions_7d, h.health_score, l.churned FROM labels l LEFT JOIN tx_pit t ON t.account_id = l.account_id AND t.label_time = l.label_time LEFT JOIN pr_pit p ON p.account_id = l.account_id AND p.label_time = l.label_time LEFT JOIN ac_pit a ON a.account_id = l.account_id AND a.label_time = l.label_time LEFT JOIN hl_pit h ON h.account_id = l.account_id AND h.label_time = l.label_time"
}

